<?php use Namira\{Permissions,AdminPanel}; ?>
<div class="admin-intro"><div><h2>بانک جامع شهدا</h2><p class="muted">شناسه و کد آرشیو ثابت می‌ماند؛ پرونده‌ها را به‌تدریج تکمیل کنید.</p></div><?php if(Permissions::allows($db,$user,'martyrs.edit')): ?><a class="primary" href="<?= e(url('admin',['tab'=>'martyrs','new'=>1])) ?>">+ افزودن شهید</a><?php endif ?></div>
