<section class="panel tablewrap"><table class="admin-table"><thead><tr><th>پرونده</th><th>شناسه / کد</th><th>رسانه / اثر هنری</th><th>وضعیت</th><th>آخرین ویرایش</th><th>عملیات</th></tr></thead><tbody><?php foreach($result['items'] as $m): ?><tr><td><div class="admin-person"><?php if($m['feature_id']&&Permissions::allows($db,$user,'media.view')): ?><img loading="lazy" src="<?= e(url('admin-media',['id'=>$m['feature_id']])) ?>" alt=""><?php else: ?><span class="admin-avatar-placeholder" aria-hidden="true">ن</span><?php endif ?><div><b><?= e($m['display_name']?:trim($m['first_name'].' '.$m['last_name'])) ?></b><small><?= e($m['father_name']!==''?'فرزند '.$m['father_name']:'نام پدر ثبت نشده') ?></small></div></div></td><td><b>#<?= fa($m['id']) ?></b><small dir="ltr"><?= e($m['code']) ?></small></td><td><?= fa($m['image_count']) ?> رسانه<small><?= fa($m['artwork_count']) ?> اثر هنری</small></td><td><span class="status-badge status-<?= e($m['status']) ?>"><?= e(['draft'=>'پیش‌نویس','pending'=>'در انتظار بررسی','needs_changes'=>'نیازمند اصلاح','approved'=>'تأییدشده','published'=>'منتشرشده','archived'=>'بایگانی'][$m['status']]??$m['status']) ?></span></td><td><?= e($m['updated_at']??$m['created_at']) ?></td><td><?php if(Permissions::allows($db,$user,'martyrs.edit')): ?><a class="outline" href="<?= e(url('admin',['tab'=>'martyrs','edit'=>$m['id']])) ?>">پرونده و ویرایش</a><?php endif ?><?php if($m['published']): ?><a class="admin-text-link" href="<?= e(url('profile',['id'=>$m['id']])) ?>" target="_blank" rel="noopener">نسخه عمومی ↗</a><?php endif ?></td></tr><?php endforeach ?></tbody></table><?php if(!$result['items']): ?><p class="empty">پرونده‌ای مطابق جست‌وجو پیدا نشد.</p><?php endif ?></section>
<?php AdminPanel::pagination($result,$_GET+['tab'=>'martyrs']); ?>
